728					continue
729				}
730				if u.CustomerID == b.CustomerID && inMonth(u.Time, b.Month) {
731					found := false
732					for _, ln := range b.Lines {
733						if ln.UsageID == u.ID {
734							found = true
735							break
736						}
737					}
738					if !found {
739						return fmt.Errorf("客户 %s 的 %s 已封账，但用量 %q 未计入账单", b.CustomerID, b.Month, u.ID)
740					}
741				}
742			}
743		}
