884		for id, a := range s.Adjustments {
885			if a == nil {
886				return fmt.Errorf("调整 %q 的数据为空", id)
887			}
888			if a.ID != id {
889				return fmt.Errorf("调整标识不一致: 键 %q / 记录 %q", id, a.ID)
890			}
891			if a.ID == "" {
892				return errors.New("存在空的调整标识")
893			}
894			if a.Amount == 0 {
895				return fmt.Errorf("调整 %q 的金额为零", id)
896			}
897			if strings.TrimSpace(a.Reason) == "" {
