908			}
909			if a.Seq < 1 || a.Seq > s.NextSeq {
910				return fmt.Errorf("调整 %q 的操作序号越界", id)
911			}
912			if prev, dup := seenSeq[a.Seq]; dup {
913				return fmt.Errorf("调整 %q 与 %q 的操作序号重复", id, prev)
914			}
915			seenSeq[a.Seq] = "调整 " + id
916			if a.Revoked {
