1057		}
1058		// 退款记录：标识、目标收款、原因、各月退款与序号都必须自洽。退款标识与
1059		// 收款、调整、更正标识命名空间相互独立，允许同名。退款只作用于未撤销
1060		// 收款的最新分配涉及的月份；首次退款后该收款不得再更正或整笔撤销，
1061		// 因此全部退款都以当前最新分配为准核验，累计不得超退。旧文件缺少退款
1062		// 记录视为无退款（Refunds 已在载入时补为空表）。
1063		for id, r := range s.Refunds {
1064			if r == nil {
1065				return fmt.Errorf("退款 %q 的数据为空", id)
1066			}
1067			if r.ID != id {
1068				return fmt.Errorf("退款标识不一致: 键 %q / 记录 %q", id, r.ID)
1069			}
1070			if r.ID == "" {
