1079			}
1080			if len(r.Allocations) == 0 {
1081				return fmt.Errorf("退款 %q 没有月份金额清单", id)
1082			}
1083			current := currentAllocations(s, p)
1084			seenMonths := make(map[string]bool)
1085			for _, al := range r.Allocations {
1086				if !validMonth(al.Month) {
1087					return fmt.Errorf("退款 %q 的月份 %q 无效", id, al.Month)
1088				}
1089				if seenMonths[al.Month] {
1090					return fmt.Errorf("退款 %q 的月份 %s 重复", id, al.Month)
1091				}
1092				seenMonths[al.Month] = true
1093				if al.Amount <= 0 {
1094					return fmt.Errorf("退款 %q 在 %s 的金额不是正整数", id, al.Month)
1095				}
1096				if allocAmountFor(current, al.Month) <= 0 {
1097					return fmt.Errorf("退款 %q 的月份 %s 不在收款 %q 的最新分配中（仅允许退最新分配涉及的月份）", id, al.Month, r.PaymentID)
1098				}
1099			}
1100			if r.Seq <= p.Seq || r.Seq > s.NextSeq {
1101				return fmt.Errorf("退款 %q 的操作序号越界", id)
1102			}
1103			if prev, dup := seenSeq[r.Seq]; dup {
1104				return fmt.Errorf("退款 %q 与 %q 的操作序号重复", id, prev)
1105			}
1106			seenSeq[r.Seq] = "退款 " + id
1107		}
1108		// 逐收款核验退款相关约束：已退款的收款不得被整笔撤销；首次退款后不得
1109		// 再出现更正（最新分配已固定）；各月累计退款不得超过该笔在该月的最新
1110		// 分配（累计超退即余额异常）。
1111		for pid, p := range s.Payments {
1112			refs := refundsFor(s, pid)
1113			if len(refs) == 0 {
1114				continue
1115			}
1116			firstRefundSeq := refs[0].Seq // refundsFor 按序号升序
1117			if p.Revoked {
1118				return fmt.Errorf("收款 %q 已发生退款（首次退款序号 %d）却又被整笔撤销（序号 %d），操作先后非法", pid, firstRefundSeq, p.RevokeSeq)
1119			}
1120			for _, c := range s.Corrections {
1121				if c.PaymentID == pid && c.Seq > firstRefundSeq {
1122					return fmt.Errorf("更正 %q 的序号 %d 晚于收款 %q 的首次退款序号 %d（首次退款后最新分配已固定），操作先后非法", c.ID, c.Seq, pid, firstRefundSeq)
1123				}
1124			}
1125			current := currentAllocations(s, p)
1126			totals := make(map[string]int64)
1127			for _, r := range refs {
1128				for _, al := range r.Allocations {
1129					sum, err := add64(totals[al.Month], al.Amount)
1130					if err != nil {
1131						return fmt.Errorf("收款 %q 在 %s 的累计退款溢出有符号 64 位整数范围，余额异常", pid, al.Month)
1132					}
1133					totals[al.Month] = sum
1134				}
1135			}
1136			for month, refunded := range totals {
1137				if alloc := allocAmountFor(current, month); refunded > alloc {
1138					return fmt.Errorf("收款 %q 在 %s 的累计退款 %d 分超过该月分配 %d 分（累计超退），余额异常", pid, month, refunded, alloc)
1139				}
1140			}
1141		}
1142		// 每张账单：当前应付（原总金额 + 全部未撤销调整净额）必须介于
1143		// 0 与有符号 64 位最大值之间；实收（全部未撤销收款按最新分配在该月
1144		// 计入并扣除退款后的合计）必须满足 0 ≤ 实收 ≤ 当前应付。越界说明
1145		// 金额与记录不一致。
1146		for key, b := range s.Bills {
1147			_, payable, err := billTotals(b, adjustmentsFor(s, b.CustomerID, b.Month))
1148			if err != nil {
1149				return fmt.Errorf("账单 %q 的调整金额与记录不一致: %w", key, err)
1150			}
1151			received, err := paymentReceived(s, b.CustomerID, b.Month)
1152			if err != nil {
1153				return fmt.Errorf("账单 %q 的收款金额与记录不一致: %w", key, err)
1154			}
1155			if received > payable {
1156				return fmt.Errorf("账单 %q 的实收 %d 分超过当前应付 %d 分", key, received, payable)
1157			}
1158		}
1159		return nil
1160	}
