1162	// validatePlanRules 校验阶梯方案的标识、名称、月费与阶梯规则本身自洽：
1163	// 月费为非负整数分，至少一档，有限上限为严格递增的正整数，最后一档无
1164	// 上限，单价非负。
1165	func validatePlanRules(p *plan) error {
1166		if p.ID == "" || p.Name == "" {
1167			return fmt.Errorf("方案 %q 的标识或名称为空", p.ID)
1168		}
1169		if p.MonthlyFee < 0 {
1170			return fmt.Errorf("方案 %q 的月费为负", p.ID)
1171		}
1172		if len(p.Tiers) == 0 {
1173			return fmt.Errorf("方案 %q 至少需要一档阶梯", p.ID)
1174		}
1175		prev := int64(0)
1176		for i, t := range p.Tiers {
1177			if t.Price < 0 {
1178				return fmt.Errorf("方案 %q 第 %d 档单价为负", p.ID, i+1)
1179			}
1180			if i == len(p.Tiers)-1 {
1181				if t.Limit != 0 {
1182					return fmt.Errorf("方案 %q 最后一档必须无上限", p.ID)
1183				}
1184			} else {
1185				if t.Limit <= 0 {
1186					return fmt.Errorf("方案 %q 第 %d 档上限必须是正整数", p.ID, i+1)
1187				}
1188				if t.Limit <= prev {
1189					return fmt.Errorf("方案 %q 的有限上限必须严格递增", p.ID)
1190				}
1191				prev = t.Limit
1192			}
1193		}
1194		return nil
1195	}
