1223	// sortedByInstant 判定用量记录是否按（解析后的时间点升序、同一时间按
1224	// 标识字典序）排列，即阶梯计价的计价顺序。
1225	func sortedByInstant(recs []*usageRecord) bool {
1226		for i := 1; i < len(recs); i++ {
1227			ti, _ := time.Parse(time.RFC3339, recs[i-1].Time)
1228			tj, _ := time.Parse(time.RFC3339, recs[i].Time)
1229			ui, uj := ti.UTC(), tj.UTC()
1230			if uj.Before(ui) || (uj.Equal(ui) && recs[i].ID <= recs[i-1].ID) {
1231				return false
1232			}
1233		}
1234		return true
1235	}
