1301	// save 整体原子落盘：先写临时文件并同步，再 rename 覆盖。
1302	// 只有完整保存成功后调用方才会向用户报告成功。
1303	func (s *state) save() error {
1304		if err := s.validate(); err != nil {
1305			return fmt.Errorf("拒绝写入不一致的数据: %w", err)
1306		}
1307		data, err := json.MarshalIndent(s, "", "  ")
1308		if err != nil {
1309			return fmt.Errorf("序列化数据失败: %w", err)
1310		}
1311		data = append(data, '\n')
1312	
1313		tmp := s.path + ".tmp"
1314		f, err := os.OpenFile(tmp, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0o644)
1315		if err != nil {
1316			return fmt.Errorf("写入临时数据文件失败: %w", err)
1317		}
1318		if _, err := f.Write(data); err != nil {
1319			f.Close()
1320			os.Remove(tmp)
1321			return fmt.Errorf("写入临时数据文件失败: %w", err)
1322		}
1323		if err := f.Sync(); err != nil {
1324			f.Close()
1325			os.Remove(tmp)
1326			return fmt.Errorf("同步数据文件失败: %w", err)
1327		}
1328		if err := f.Close(); err != nil {
1329			os.Remove(tmp)
1330			return fmt.Errorf("关闭数据文件失败: %w", err)
1331		}
1332		if err := os.Rename(tmp, s.path); err != nil {
1333			os.Remove(tmp)
1334			return fmt.Errorf("替换数据文件失败: %w", err)
1335		}
1336		if dir, err := os.Open(filepath.Dir(s.path)); err == nil {
1337			dir.Sync()
1338			dir.Close()
1339		}
1340		return nil
1341	}
