253	func cmdCustomerAdd(dir, id, name, priceText string) error {
254		if strings.TrimSpace(id) == "" {
255			return fmt.Errorf("客户标识不能为空")
256		}
257		if strings.TrimSpace(name) == "" {
258			return fmt.Errorf("客户名称不能为空")
259		}
260		price, err := parsePrice(priceText)
261		if err != nil {
262			return err
263		}
264	
265		s, err := loadStore(dir)
266		if err != nil {
267			return err
268		}
269		if _, exists := s.Customers[id]; exists {
270			return fmt.Errorf("客户标识 %q 已存在，客户单价创建后不可修改", id)
271		}
272		s.Customers[id] = &customer{ID: id, Name: name, Price: price}
273		if err := s.save(); err != nil {
274			return err
275		}
276		fmt.Fprintf(stdout, "已登记客户 %q（%s），固定单价 %d 分（%s）\n", id, name, price, moneyFen(price))
277		return nil
278	}
