292	// parsedRow 是导入文件中一行解析后的候选用量。
293	type parsedRow struct {
294		line int // 文件中的行号（含表头），用于报错定位
295		rec  usageRecord
296		t    time.Time
297	}
298	
299	func cmdUsageImport(dir, file string) error {
300		var reader io.ReadCloser
301		var source string
302		if file == "-" {
303			reader = io.NopCloser(os.Stdin)
304			source = "标准输入"
305		} else {
306			f, err := os.Open(file)
307			if err != nil {
308				return fmt.Errorf("无法打开用量文件 %s: %w", file, err)
309			}
310			reader = f
311			source = file
312		}
313		defer reader.Close()
314	
315		rows, parseErrs := parseUsageFile(reader)
316	
317		s, err := loadStore(dir)
318		if err != nil {
319			return err
320		}
321	
322		// 先校验：任何问题都在此阶段收集，全部通过后才一次性修改并保存，
323		// 保证“整批导入先校验再生效”，失败不留下任何新用量。
324		var problems []string
325		problems = append(problems, parseErrs...)
326	
327		accepted := make(map[string]*parsedRow) // 本批内首次出现、内容确定的记录
328		var ordered []*parsedRow
329		newCount, dupCount := 0, 0
330	
331		for _, r := range rows {
332			cust, ok := s.Customers[r.rec.CustomerID]
333			if !ok {
334				problems = append(problems, fmt.Sprintf("第 %d 行：客户标识 %q 不存在", r.line, r.rec.CustomerID))
335				continue
336			}
337	
338			// 去重判定同时对“库中已有”和“本文件内已出现”生效，且先于暂停、
339			// 封账与金额预检：已存在记录（含已撤回记录）按客户、解析后的时间点
340			// 和数量与原内容判重，相同重放计入重复跳过——即使该月后来已封账、
341			// 暂停或后续方案计价会溢出也不受阻；已撤回记录的重放不会恢复记录。
342			var existing *usageRecord
343			if inStore, ok := s.Usage[r.rec.ID]; ok {
344				existing = inStore
345			} else if inBatch, ok := accepted[r.rec.ID]; ok {
346				existing = &inBatch.rec
347			}
348			if existing != nil {
349				if !sameUsage(existing, &r.rec, r.t) {
350					problems = append(problems, fmt.Sprintf("第 %d 行：用量标识 %q 已存在但内容不同（已有客户=%s 时间=%s 数量=%d）",
351						r.line, r.rec.ID, existing.CustomerID, existing.Time, existing.Quantity))
352					continue
353				}
354				dupCount++
355				continue
356			}
357	
358			// 以下为全新用量：暂停、封账及当前方案下金额预检只约束全新用量。
359			// 暂停月的新用量一律拒绝：按记录时间换算的 UTC 月份判断，处于任一
360			// 暂停区间（含起月、不含结束月）即整批失败并指出行号。
361			rowMonth := r.t.UTC().Format("2006-01")
362			if s.isSuspendedMonth(r.rec.CustomerID, rowMonth) {
363				problems = append(problems, fmt.Sprintf("第 %d 行：客户 %s 的 %s 处于暂停区间，暂停服务期间不接收用量（新用量 %q 被拒绝）",
364					r.line, r.rec.CustomerID, rowMonth, r.rec.ID))
365				continue
366			}
367			// 终止月（含）起的新用量一律拒绝：订阅已终止，永久结束后续服务。
368			if s.isTerminatedMonth(r.rec.CustomerID, rowMonth) {
369				problems = append(problems, fmt.Sprintf("第 %d 行：客户 %s 的 %s 不早于终止月 %s，订阅已终止不接收新用量（新用量 %q 被拒绝）",
370					r.line, r.rec.CustomerID, rowMonth, s.Terminations[r.rec.CustomerID].Month, r.rec.ID))
371				continue
372			}
373			// 金额可行性预检：固定单价客户检查 数量×单价；阶梯客户按记录时间
374			// 换算的 UTC 月份的有效方案，以单条数量从零计价，检查分段金额不
375			// 溢出（金额单位：分）。
376			if cust.PlanID == "" {
377				if _, err := mul64(r.rec.Quantity, cust.Price); err != nil {
378					problems = append(problems, fmt.Sprintf("第 %d 行：数量 %d × 单价 %d 金额溢出有符号 64 位整数范围", r.line, r.rec.Quantity, cust.Price))
379					continue
380				}
381			} else {
382				rec := r.rec
383				planID := s.effectivePlanID(cust, rowMonth)
384				if _, err := tieredPrice(s.Plans[planID].Tiers, []*usageRecord{&rec}); err != nil {
385					problems = append(problems, fmt.Sprintf("第 %d 行：按 %s 月有效方案 %q 对单条数量从零计价失败：%v", r.line, rowMonth, planID, err))
386					continue
387				}
388			}
389	
390			// 全新标识：不得进入该客户已封账的 UTC 自然月。
391			if s.sealed(r.rec.CustomerID, rowMonth) {
392				problems = append(problems, fmt.Sprintf("第 %d 行：客户 %s 的 %s 已封账，新用量 %q 不得进入",
393					r.line, r.rec.CustomerID, rowMonth, r.rec.ID))
394				continue
395			}
396	
397			rr := r
398			accepted[r.rec.ID] = rr
399			ordered = append(ordered, rr)
400			newCount++
401		}
402	
403		if len(problems) > 0 {
404			return fmt.Errorf("导入失败，整批未生效（共 %d 个问题）：\n  %s", len(problems), strings.Join(problems, "\n  "))
405		}
406	
407		for _, r := range ordered {
408			rec := r.rec
409			s.Usage[rec.ID] = &rec
410		}
411		if err := s.save(); err != nil {
412			return err
413		}
414		fmt.Fprintf(stdout, "导入完成（%s）：新增 %d 条，重复跳过 %d 条\n", source, newCount, dupCount)
415		return nil
416	}
