531	func cmdBillSettle(dir, customerID, month string) error {
532		if !validMonth(month) {
533			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
534		}
535		s, err := loadStore(dir)
536		if err != nil {
537			return err
538		}
539		cust, ok := s.Customers[customerID]
540		if !ok {
541			return fmt.Errorf("客户标识 %q 不存在", customerID)
542		}
543	
544		// 暂停月无论方案月费多少都拒绝结算：不封账、不生成零金额账单。
545		if s.isSuspendedMonth(customerID, month) {
546			return fmt.Errorf("客户 %s 的 %s 处于暂停区间，暂停服务期间不产生月费账单，拒绝结算且不封账", customerID, month)
547		}
548		// 终止月（含）起拒绝结算：订阅已终止，不结算、不封账、不收月费、不生成
549		// 零金额账单；终止前月份仍按原规则补结算。
550		if s.isTerminatedMonth(customerID, month) {
551			return fmt.Errorf("客户 %s 的 %s 不早于终止月 %s，订阅已终止：不结算、不封账、不收月费、不生成零金额账单",
552				customerID, month, s.Terminations[customerID].Month)
553		}
554	
555		key := billKey(customerID, month)
556		if existing, ok := s.Bills[key]; ok {
557			// 幂等：同一客户同一月份重复结算，直接返回原账单，
558			// 不重新计费、不产生新账单或调整、不落盘。
559			fmt.Fprintf(stdout, "客户 %s 的 %s 已结算，返回原账单（幂等，不重新计费）：\n\n", customerID, month)
560			printBill(existing, cust, s)
561			return nil
562		}
563	
564		// 归集该客户 UTC 自然月内的全部有效（未撤回）用量，区间为左闭右开
565		// [月初, 下月初)。有效方案月费大于 0 的阶梯客户即使无用量也须出账
566		// （收取一次整月月费）；月费为 0 的方案与固定单价客户无用量时仍拒绝
567		// 结算且不封账。
568		inMonthRecs := monthUsage(s, customerID, month)
569		if len(inMonthRecs) == 0 && !monthlyFeeBillable(s, cust, month) {
570			return fmt.Errorf("客户 %s 在 %s 没有用量，拒绝结算且不封账", customerID, month)
571		}
572	
573		// 绑定阶梯方案的客户走按月累计分档计价；固定单价客户保持原路径。
574		if cust.PlanID != "" {
575			return settleTiered(s, cust, month, inMonthRecs)
576		}
577	
578		b, err := buildFixedBill(cust, month, inMonthRecs)
579		if err != nil {
580			return fmt.Errorf("%v，拒绝结算且不封账", err)
581		}
582		s.Bills[key] = b
583	
584		// 账单与封账状态在同一次原子保存中一起持久化；保存失败则一切不生效。
585		if err := s.save(); err != nil {
586			delete(s.Bills, key)
587			return err
588		}
589		fmt.Fprintf(stdout, "结算完成，客户 %s 的 %s 已封账：\n\n", customerID, month)
590		printBill(b, cust, s)
591		return nil
592	}
