614	// monthUsage 归集客户在某 UTC 自然月（左闭右开 [月初, 下月初)）内的全部
615	// 有效（未撤回）用量，并按计价顺序（解析后的时间点升序、同一时间按标识
616	// 字典序）排列。已撤回用量不计费用，不参与单笔及批量结算；阶梯计价将剩余
617	// 记录按原有时间点及标识顺序从零累计重新分档。
618	func monthUsage(s *state, customerID, month string) []*usageRecord {
619		var recs []*usageRecord
620		for _, u := range s.Usage {
621			if s.isWithdrawn(u.ID) {
622				continue
623			}
624			if u.CustomerID == customerID && inMonth(u.Time, month) {
625				recs = append(recs, u)
626			}
627		}
628		sortByInstant(recs)
629		return recs
630	}
