768	// historyEvents 把调整与撤销展开为按操作序号排序的可读历史条目。
769	func historyEvents(adjs []*adjustment) []string {
770		type event struct {
771			seq  int64
772			text string
773		}
774		var events []event
775		for _, a := range adjs {
776			events = append(events, event{a.Seq, fmt.Sprintf("调整 %s：%s %+d 分（%s），原因：%s，当前状态：%s",
777				a.ID, adjustKind(a.Amount), a.Amount, moneyFen(a.Amount), a.Reason, adjustStatus(a))})
778			if a.Revoked {
779				events = append(events, event{a.RevokeSeq, fmt.Sprintf("撤销 %s：原因：%s（关联调整 %s 的%s %+d 分）",
780					a.ID, a.RevokeReason, a.ID, adjustKind(a.Amount), a.Amount)})
781			}
782		}
783		sort.Slice(events, func(i, j int) bool { return events[i].seq < events[j].seq })
784		out := make([]string, len(events))
785		for i, ev := range events {
786			out[i] = ev.text
787		}
788		return out
789	}
