873	func cmdBillAdjust(dir, customerID, month, adjID, amountText, reason string) error {
874		if !validMonth(month) {
875			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
876		}
877		if strings.TrimSpace(adjID) == "" {
878			return fmt.Errorf("调整标识不能为空")
879		}
880		amount, err := parseAmount(amountText)
881		if err != nil {
882			return err
883		}
884		if strings.TrimSpace(reason) == "" {
885			return fmt.Errorf("调整原因不能为空")
886		}
887	
888		s, err := loadStore(dir)
889		if err != nil {
890			return err
891		}
892		if _, ok := s.Customers[customerID]; !ok {
893			return fmt.Errorf("客户标识 %q 不存在", customerID)
894		}
895		b, ok := s.Bills[billKey(customerID, month)]
896		if !ok {
897			return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算），费用调整只能作用于已存在账单", customerID, month)
898		}
899	
900		if existing, ok := s.Adjustments[adjID]; ok {
901			// 相同标识按客户、月份、金额、原因判断重复：内容相同返回已保存
902			// 记录，不再次增减应付；已撤销的重放仍返回已撤销状态，不重新生效。
903			if existing.CustomerID == customerID && existing.Month == month &&
904				existing.Amount == amount && existing.Reason == reason {
905				fmt.Fprintf(stdout, "调整 %q 已存在且内容相同，返回已保存记录（不重复增减应付）：\n\n", adjID)
906				printAdjustment(existing, s)
907				return nil
908			}
909			return fmt.Errorf("调整标识 %q 已存在但内容不同（已有：客户=%s 月份=%s 金额=%d 原因=%q），拒绝复用",
910				adjID, existing.CustomerID, existing.Month, existing.Amount, existing.Reason)
911		}
912	
913		// 应付可行性预检：原总金额 + 全部未撤销调整 + 本次金额必须落在
914		// [0, 有符号 64 位最大值] 内，且不得低于已登记实收，否则拒绝且
915		// 不占用该调整标识。
916		_, payable, err := billTotals(b, adjustmentsFor(s, customerID, month))
917		if err != nil {
918			return fmt.Errorf("账单当前应付异常，拒绝调整: %w", err)
919		}
920		received, err := paymentReceived(s, customerID, month)
921		if err != nil {
922			return fmt.Errorf("实收累计异常，拒绝调整: %w", err)
923		}
924		newPayable, err := addSigned64(payable, amount)
925		if err != nil {
926			return fmt.Errorf("调整后当前应付超出有符号 64 位最大值（当前 %d 分，本次 %+d 分），拒绝调整", payable, amount)
927		}
928		if newPayable < 0 {
929			return fmt.Errorf("调整后当前应付将为 %d 分（小于 0，当前 %d 分，本次 %+d 分），拒绝调整", newPayable, payable, amount)
930		}
931		if newPayable < received {
932			return fmt.Errorf("调整后当前应付 %d 分将低于实收 %d 分（当前 %d 分，本次 %+d 分），拒绝调整；可先撤销误登记的收款再重试",
933				newPayable, received, payable, amount)
934		}
935	
936		a := &adjustment{
937			ID:         adjID,
938			CustomerID: customerID,
939			Month:      month,
940			Amount:     amount,
941			Reason:     reason,
942			CreatedAt:  time.Now().UTC().Format(time.RFC3339),
943		}
944		s.NextSeq++
945		a.Seq = s.NextSeq
946		s.Adjustments[adjID] = a
947	
948		// 调整记录与序号在同一次原子保存中持久化；保存失败则一切不生效，
949		// 该调整标识不被占用。
950		if err := s.save(); err != nil {
951			delete(s.Adjustments, adjID)
952			s.NextSeq--
953			return err
954		}
955		fmt.Fprintf(stdout, "已登记%s调整 %q，客户 %s 的 %s 当前应付 %d 分（%s）：\n\n",
956			adjustKind(amount), adjID, customerID, month, newPayable, moneyFen(newPayable))
957		printAdjustment(a, s)
958		return nil
959	}
