961	func cmdBillRevoke(dir, adjID, reason string) error {
962		if strings.TrimSpace(adjID) == "" {
963			return fmt.Errorf("调整标识不能为空")
964		}
965		if strings.TrimSpace(reason) == "" {
966			return fmt.Errorf("撤销原因不能为空")
967		}
968	
969		s, err := loadStore(dir)
970		if err != nil {
971			return err
972		}
973		a, ok := s.Adjustments[adjID]
974		if !ok {
975			return fmt.Errorf("调整标识 %q 不存在，无法撤销", adjID)
976		}
977	
978		if a.Revoked {
979			// 相同标识与相同原因重复撤销：幂等成功，不新增记录；
980			// 改用其他原因则拒绝。
981			if a.RevokeReason == reason {
982				fmt.Fprintf(stdout, "调整 %q 已撤销且撤销原因相同，幂等返回（不新增记录）：\n\n", adjID)
983				printAdjustment(a, s)
984				return nil
985			}
986			return fmt.Errorf("调整 %q 已撤销（撤销原因 %q），改用其他原因重复撤销被拒绝", adjID, a.RevokeReason)
987		}
988	
989		// 撤销只取消该笔调整的金额影响；若撤销后当前应付越界或低于实收则
990		// 拒绝，该调整仍保持有效，可先撤销误登记的收款或在其他合法调整
991		// 改变余额后重试。
992		b := s.Bills[billKey(a.CustomerID, a.Month)] // 载入时已校验存在
993		_, payable, err := billTotals(b, adjustmentsFor(s, a.CustomerID, a.Month))
994		if err != nil {
995			return fmt.Errorf("账单当前应付异常，拒绝撤销: %w", err)
996		}
997		received, err := paymentReceived(s, a.CustomerID, a.Month)
998		if err != nil {
999			return fmt.Errorf("实收累计异常，拒绝撤销: %w", err)
1000		}
1001		neg, err := neg64(a.Amount)
1002		if err != nil {
1003			return fmt.Errorf("撤销后当前应付将超出有符号 64 位最大值，拒绝撤销；该调整仍有效，可在其他合法调整改变余额后重试")
1004		}
1005		newPayable, err := addSigned64(payable, neg)
1006		if err != nil {
1007			return fmt.Errorf("撤销后当前应付将超出有符号 64 位最大值（当前 %d 分，取消 %+d 分），拒绝撤销；该调整仍有效，可在其他合法调整改变余额后重试",
1008				payable, a.Amount)
1009		}
1010		if newPayable < 0 {
1011			return fmt.Errorf("撤销后当前应付将为 %d 分（小于 0，当前 %d 分，取消 %+d 分），拒绝撤销；该调整仍有效，可在其他合法调整改变余额后重试",
1012				newPayable, payable, a.Amount)
1013		}
1014		if newPayable < received {
1015			return fmt.Errorf("撤销后当前应付 %d 分将低于实收 %d 分（当前 %d 分，取消 %+d 分），拒绝撤销；可先撤销误登记的收款再重试",
1016				newPayable, received, payable, a.Amount)
1017		}
1018	
1019		a.Revoked = true
1020		a.RevokeReason = reason
1021		a.RevokedAt = time.Now().UTC().Format(time.RFC3339)
1022		s.NextSeq++
1023		a.RevokeSeq = s.NextSeq
1024	
1025		// 撤销信息与原记录在同一次原子保存中持久化；保存失败则一切不生效。
1026		if err := s.save(); err != nil {
1027			a.Revoked = false
1028			a.RevokeReason = ""
1029			a.RevokedAt = ""
1030			a.RevokeSeq = 0
1031			s.NextSeq--
1032			return err
1033		}
1034		fmt.Fprintf(stdout, "已撤销调整 %q（%s %+d 分），客户 %s 的 %s 当前应付 %d 分（%s）：\n\n",
1035			adjID, adjustKind(a.Amount), a.Amount, a.CustomerID, a.Month, newPayable, moneyFen(newPayable))
1036		printAdjustment(a, s)
1037		return nil
1038	}
1039	
1040	// printAdjustment 输出单笔调整记录及其当前状态；payable 取自当前库状态。
1041	func printAdjustment(a *adjustment, s *state) {
1042		b := s.Bills[billKey(a.CustomerID, a.Month)]
1043		_, payable, _ := billTotals(b, adjustmentsFor(s, a.CustomerID, a.Month))
1044		fmt.Fprintf(stdout, "调整标识：%s\n", a.ID)
1045		fmt.Fprintf(stdout, "客户：%s\n", a.CustomerID)
1046		fmt.Fprintf(stdout, "月份：%s\n", a.Month)
1047		fmt.Fprintf(stdout, "调整金额：%+d 分（%s，%s）\n", a.Amount, moneyFen(a.Amount), adjustKind(a.Amount))
1048		fmt.Fprintf(stdout, "原因：%s\n", a.Reason)
1049		if a.Revoked {
1050			fmt.Fprintf(stdout, "当前状态：已撤销（撤销原因：%s）\n", a.RevokeReason)
1051		} else {
1052			fmt.Fprintf(stdout, "当前状态：生效中\n")
1053		}
1054		fmt.Fprintf(stdout, "当前应付：%d 分（%s）\n", payable, moneyFen(payable))
1055	}
