1061		if err != nil {
1062			return 0, fmt.Errorf("收款金额 %q 不是有符号 64 位整数范围内的整数: %w", text, err)
1063		}
1064		if amount <= 0 {
1065			return 0, fmt.Errorf("收款金额必须是正整数分，收到 %d", amount)
1066		}
1067		return amount, nil
1068	}
