1196		if p.Revoked {
1197			fmt.Fprintf(stdout, "当前状态：已撤销（撤销原因：%s）\n", p.RevokeReason)
1198		} else {
1199			fmt.Fprintf(stdout, "当前状态：实收中\n")
1200		}
1201		fmt.Fprintf(stdout, "首次分配（登记时按最早欠款账期自动确定，永久保留）：%s\n", formatAllocations(p.Allocations))
1202		if sameAllocations(current, p.Allocations) {
1203			fmt.Fprintf(stdout, "最新分配：%s（与首次分配相同）\n", formatAllocations(current))
1204		} else {
1205			fmt.Fprintf(stdout, "最新分配（经更正，以最新为准）：%s\n", formatAllocations(current))
1206		}
1207		fmt.Fprintln(stdout, "首次与最新分配所涉月份当前余额：")
1208		for _, m := range unionMonths(p.Allocations, current) {
1209			b := s.Bills[billKey(p.CustomerID, m)] // 载入时已校验存在
1210			_, payable, _ := billTotals(b, adjustmentsFor(s, p.CustomerID, m))
1211			received, _ := paymentReceived(s, p.CustomerID, m)
1212			fmt.Fprintf(stdout, "  月份 %s：首次分配 %d 分，最新分配 %d 分；当前应付 %d 分（%s），实收 %d 分（%s），未收余额 %d 分（%s）\n",
1213				m, allocAmountFor(p.Allocations, m), allocAmountFor(current, m),
1214				payable, moneyFen(payable), received, moneyFen(received), payable-received, moneyFen(payable-received))
1215		}
1216	}
