1218	// parseAllocations 解析 <YYYY-MM:金额分> 形式的分配列表：至少一项，
1219	// 月份不得重复，每项金额为正整数分。
1220	func parseAllocations(args []string) ([]paymentAllocation, error) {
1221		if len(args) == 0 {
1222			return nil, fmt.Errorf("分配列表不能为空，至少需要一项 <YYYY-MM:金额分>")
1223		}
1224		seen := make(map[string]bool)
1225		allocs := make([]paymentAllocation, 0, len(args))
1226		for _, arg := range args {
1227			parts := strings.Split(arg, ":")
1228			if len(parts) != 2 {
1229				return nil, fmt.Errorf("分配项 %q 格式非法，应为 YYYY-MM:金额分（如 2026-09:500）", arg)
1230			}
1231			month := strings.TrimSpace(parts[0])
1232			if !validMonth(month) {
1233				return nil, fmt.Errorf("分配项 %q 的月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", arg, parts[0])
1234			}
1235			if seen[month] {
1236				return nil, fmt.Errorf("分配月份 %s 重复，拒绝登记", month)
1237			}
1238			seen[month] = true
1239			amount, err := parsePositiveAmount(parts[1])
1240			if err != nil {
1241				return nil, fmt.Errorf("分配项 %q 的金额无效: %w", arg, err)
1242			}
1243			allocs = append(allocs, paymentAllocation{Month: month, Amount: amount})
1244		}
1245		return allocs, nil
1246	}
