1380	func cmdBillUnpay(dir, payID, reason string) error {
1381		if strings.TrimSpace(payID) == "" {
1382			return fmt.Errorf("收款标识不能为空")
1383		}
1384		if strings.TrimSpace(reason) == "" {
1385			return fmt.Errorf("撤销原因不能为空")
1386		}
1387	
1388		s, err := loadStore(dir)
1389		if err != nil {
1390			return err
1391		}
1392		p, ok := s.Payments[payID]
1393		if !ok {
1394			return fmt.Errorf("收款标识 %q 不存在，无法撤销", payID)
1395		}
1396	
1397		if p.Revoked {
1398			// 相同标识与相同原因重复撤销：幂等成功，不新增历史；
1399			// 改用其他原因则拒绝。
1400			if p.RevokeReason == reason {
1401				fmt.Fprintf(stdout, "收款 %q 已撤销且撤销原因相同，幂等返回（不新增历史）：\n\n", payID)
1402				printPayment(p, s)
1403				return nil
1404			}
1405			return fmt.Errorf("收款 %q 已撤销（撤销原因 %q），改用其他原因重复撤销被拒绝", payID, p.RevokeReason)
1406		}
1407	
1408		// 首次退款后该收款的最新分配固定，拒绝整笔撤销；退款记录永久保留且
1409		// 不可撤销，实收按扣除退款后的余额继续计算。无退款的收款仍按原规则
1410		// 处理。
1411		if paymentHasRefunds(s, payID) {
1412			return fmt.Errorf("收款 %q 已发生退款，最新分配已固定，拒绝整笔撤销；如需退回余款请继续登记部分退款", payID)
1413		}
1414	
1415		// 撤销整笔生效：取消该笔在全部分配月份上的最新实收（经更正的以最新
1416		// 分配为准），不接受部分撤销；不改变应付、其他收款或调整，原收款、
1417		// 分配、更正与撤销原因永久保留。
1418		p.Revoked = true
1419		p.RevokeReason = reason
1420		p.RevokedAt = time.Now().UTC().Format(time.RFC3339)
1421		s.NextSeq++
1422		p.RevokeSeq = s.NextSeq
1423	
1424		// 撤销信息与原记录在同一次原子保存中持久化；保存失败则一切不生效。
1425		if err := s.save(); err != nil {
1426			p.Revoked = false
1427			p.RevokeReason = ""
1428			p.RevokedAt = ""
1429			p.RevokeSeq = 0
1430			s.NextSeq--
1431			return err
1432		}
1433		fmt.Fprintf(stdout, "已撤销收款 %q（总额 %d 分，%s），取消最新分配：\n", payID, p.Total, moneyFen(p.Total))
1434		printAllocationBalances(s, p, currentAllocations(s, p))
1435		fmt.Fprintln(stdout)
1436		printPayment(p, s)
1437		return nil
1438	}
