1480	// --- 收款分配更正 ---
1481	
1482	func cmdBillCorrect(dir, payID, corrID, reason string, allocArgs []string) error {
1483		if strings.TrimSpace(payID) == "" {
1484			return fmt.Errorf("收款标识不能为空")
1485		}
1486		if strings.TrimSpace(corrID) == "" {
1487			return fmt.Errorf("更正标识不能为空")
1488		}
1489		if strings.TrimSpace(reason) == "" {
1490			return fmt.Errorf("更正原因不能为空")
1491		}
1492		allocs, err := parseAllocations(allocArgs)
1493		if err != nil {
1494			return err
1495		}
1496		// 分配顺序不影响更正身份：统一按月份升序保存与比较。
1497		sort.Slice(allocs, func(i, j int) bool { return allocs[i].Month < allocs[j].Month })
1498	
1499		s, err := loadStore(dir)
1500		if err != nil {
1501			return err
1502		}
1503		p, ok := s.Payments[payID]
1504		if !ok {
1505			return fmt.Errorf("收款标识 %q 不存在，无法更正分配", payID)
1506		}
1507	
1508		if existing, ok := s.Corrections[corrID]; ok {
1509			// 相同标识按目标收款、原因与新月份-金额对应关系判重（列表顺序无关）：
1510			// 内容相同返回原更正记录，不改分配、不增历史；后续更正或收款撤销
1511			// 不影响此规则。任何一项不同（含跨收款复用）均拒绝。
1512			if existing.PaymentID == payID && existing.Reason == reason && sameAllocations(existing.Allocations, allocs) {
1513				fmt.Fprintf(stdout, "更正 %q 已存在且内容相同，返回原更正记录（不改分配、不增历史）：\n\n", corrID)
1514				printCorrection(existing, s)
1515				return nil
1516			}
1517			return fmt.Errorf("更正标识 %q 已存在但内容不同（已有：收款=%s 原因=%q 新分配=%s），拒绝复用",
1518				corrID, existing.PaymentID, existing.Reason, formatAllocations(existing.Allocations))
1519		}
1520	
1521		// 新增更正只允许未撤销收款。
1522		if p.Revoked {
1523			return fmt.Errorf("收款 %q 已撤销（撤销原因 %q），不能新增分配更正", payID, p.RevokeReason)
1524		}
1525	
1526		// 首次退款后该收款的最新分配固定，拒绝新增分配更正；已有更正的相同
1527		// 重放已在上面按原记录返回，不受此限。无退款的收款仍按原规则处理。
1528		if paymentHasRefunds(s, payID) {
1529			return fmt.Errorf("收款 %q 已发生退款，最新分配已固定，拒绝新增分配更正", payID)
1530		}
1531	
1532		// 新分配合计必须等于原收款总额（不重复收钱也不多收），全程整数运算。
1533		var sum int64
1534		for _, al := range allocs {
1535			sum, err = add64(sum, al.Amount)
1536			if err != nil {
1537				return fmt.Errorf("新分配金额合计溢出有符号 64 位整数范围，拒绝更正")
1538			}
1539		}
1540		if sum != p.Total {
1541			return fmt.Errorf("新分配合计 %d 分与原收款 %q 的总额 %d 分不一致，拒绝更正", sum, payID, p.Total)
1542		}
1543		// 新分配月份须是原客户的已结算账单。
1544		for _, al := range allocs {
1545			if _, ok := s.Bills[billKey(p.CustomerID, al.Month)]; !ok {
1546				return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算），更正只能分配到已存在账单", p.CustomerID, al.Month)
1547			}
1548		}
1549	
1550		// 以当前最新分配为起点：撤去该笔当前分配再计入新分配后，涉及月份
1551		// 均须满足 0 ≤ 实收 ≤ 应付；其他收款不变，全部合法才整笔生效。
1552		current := currentAllocations(s, p)
1553		for _, m := range unionMonths(current, allocs) {
1554			b := s.Bills[billKey(p.CustomerID, m)] // 载入时已校验存在
1555			_, payable, err := billTotals(b, adjustmentsFor(s, p.CustomerID, m))
1556			if err != nil {
1557				return fmt.Errorf("客户 %s 的 %s 当前应付异常，拒绝更正: %w", p.CustomerID, m, err)
1558			}
1559			received, err := paymentReceived(s, p.CustomerID, m)
1560			if err != nil {
1561				return fmt.Errorf("客户 %s 的 %s 实收累计异常，拒绝更正: %w", p.CustomerID, m, err)
1562			}
1563			// 该笔收款未撤销，其实收必然包含当前分配，撤去不会变负。
1564			received -= allocAmountFor(current, m)
1565			received, err = add64(received, allocAmountFor(allocs, m))
1566			if err != nil {
1567				return fmt.Errorf("客户 %s 的 %s 更正后实收溢出有符号 64 位整数范围，拒绝更正", p.CustomerID, m)
1568			}
1569			if received > payable {
1570				return fmt.Errorf("更正后客户 %s 的 %s 实收 %d 分将超过当前应付 %d 分，拒绝更正；全部状态保持不变",
1571					p.CustomerID, m, received, payable)
1572			}
1573		}
1574	
1575		c := &correction{
1576			ID:          corrID,
1577			PaymentID:   payID,
1578			Reason:      reason,
1579			Allocations: allocs,
1580			CreatedAt:   time.Now().UTC().Format(time.RFC3339),
1581		}
1582		s.NextSeq++
1583		c.Seq = s.NextSeq
1584		s.Corrections[corrID] = c
1585	
1586		// 更正记录、序号与余额状态在同一次原子保存中持久化；保存失败则
1587		// 一切不生效，该更正标识不被占用。
1588		if err := s.save(); err != nil {
1589			delete(s.Corrections, corrID)
1590			s.NextSeq--
1591			return err
1592		}
1593		fmt.Fprintf(stdout, "已登记收款分配更正 %q（关联收款 %q）：\n\n", corrID, payID)
1594		printCorrection(c, s)
1595		return nil
1596	}
1597	
1598	// unionMonths 返回两个分配列表涉及月份的并集，按月份升序。
1599	func unionMonths(a, b []paymentAllocation) []string {
1600		set := make(map[string]bool, len(a)+len(b))
1601		for _, al := range a {
1602			set[al.Month] = true
1603		}
1604		for _, al := range b {
1605			set[al.Month] = true
1606		}
1607		months := make([]string, 0, len(set))
1608		for m := range set {
1609			months = append(months, m)
1610		}
1611		sort.Strings(months)
1612		return months
1613	}
1614	
1615	// allocationBefore 返回一次更正发生前该收款生效的分配：上一条更正的
1616	// 新分配，或（首次更正时）收款的原始分配。
1617	func allocationBefore(s *state, c *correction) []paymentAllocation {
1618		before := s.Payments[c.PaymentID].Allocations // 载入时已校验存在
1619		var latest *correction
1620		for _, o := range s.Corrections {
1621			if o.PaymentID == c.PaymentID && o.Seq < c.Seq && (latest == nil || o.Seq > latest.Seq) {
1622				latest = o
1623			}
1624		}
1625		if latest != nil {
1626			before = latest.Allocations
1627		}
1628		return before
1629	}
1630	
1631	// printCorrection 输出单笔更正记录：关联收款、标识、原因、完整前后分配，
1632	// 以及前后分配涉及月份的当前余额。
1633	func printCorrection(c *correction, s *state) {
1634		p := s.Payments[c.PaymentID] // 载入时已校验存在
1635		before := allocationBefore(s, c)
1636		fmt.Fprintf(stdout, "更正标识：%s\n", c.ID)
1637		fmt.Fprintf(stdout, "关联收款：%s（客户 %s，总额 %d 分（%s），备注：%s）\n",
1638			p.ID, p.CustomerID, p.Total, moneyFen(p.Total), p.Note)
1639		fmt.Fprintf(stdout, "原因：%s\n", c.Reason)
1640		fmt.Fprintf(stdout, "更正前分配：%s\n", formatAllocations(before))
1641		fmt.Fprintf(stdout, "更正后分配：%s\n", formatAllocations(c.Allocations))
1642		fmt.Fprintln(stdout, "涉及月份当前余额：")
1643		for _, m := range unionMonths(before, c.Allocations) {
1644			b := s.Bills[billKey(p.CustomerID, m)] // 载入时已校验存在
1645			_, payable, _ := billTotals(b, adjustmentsFor(s, p.CustomerID, m))
1646			received, _ := paymentReceived(s, p.CustomerID, m)
1647			fmt.Fprintf(stdout, "  月份 %s：本笔分配 %d 分 → %d 分；当前应付 %d 分（%s），实收 %d 分（%s），未收余额 %d 分（%s）\n",
1648				m, allocAmountFor(before, m), allocAmountFor(c.Allocations, m),
1649				payable, moneyFen(payable), received, moneyFen(received), payable-received, moneyFen(payable-received))
1650		}
1651	}
1652	
1653	// --- 账后对账流水 ---
1654	
1655	// ledgerEvent 是某张已结算账单账后流水中的一个事件：调整、撤销调整、收款、
1656	// 分配更正、撤销收款或退款。事件按全局操作序号升序回放；撤销在其发生序号抵消
1657	// 对应原操作，已撤销记录在撤销之前仍计入，不按当前撤销状态删除原事件；
1658	// 更正在其发生序号把关联收款在本账单的分配由前值替换为后值；退款在其发生
1659	// 序号减少本账单实收，不可撤销。
1660	type ledgerEvent struct {
1661		seq           int64  // 全局操作序号（调整/收款/更正/退款及其撤销共用）
1662		kind          string // 事件类型：调整 / 撤销调整 / 收款 / 更正 / 撤销收款 / 退款
1663		refID         string // 原记录标识（调整标识、收款标识或更正标识）
1664		deltaPayable  int64  // 对当前应付的影响（分，带符号）
1665		deltaReceived int64  // 对实收的影响（分，带符号）
1666		note          string // 原因（调整/更正类）或备注（收款类）
1667		linkSeq       int64  // 撤销事件关联的原操作序号；非撤销事件为 0
1668		payTotal      int64  // 收款类事件：汇款总额
1669		payAlloc      int64  // 收款类事件：本账单分配（撤销收款事件为被取消的最新分配；退款事件为本账单退款额）
1670		payID         string // 更正/退款事件：关联收款标识
1671		beforeAlloc   int64  // 更正事件：本账单更正前分配
1672		afterAlloc    int64  // 更正事件：本账单更正后分配
1673		afterPayable  int64  // 事件后的应付（回放时填充）
1674		afterReceived int64  // 事件后的实收（回放时填充）
1675	}
1676	
1677	// billLedger 返回目标账单的一条按操作序号升序的账后流水，事件之后的三项
1678	// 余额已逐步填充。业务归属、金额影响（调整/撤销/收款/更正/撤销收款/退款）
1679	// 与完整性核验都来自与 bill reconcile 共用的 postbill 计算，本处只取该账单
1680	// 那一条流水：
1681	//
1682	//   - 以原总金额为初始应付、零实收为起点；
1683	//   - 回放覆盖完整流水（不受查询截止序号限制），序号重复、撤销先于原操作，
1684	//     或任一事件之后不满足 0 ≤ 实收 ≤ 应付 ≤ 有符号 64 位最大值，都视为
1685	//     数据异常并拒绝，即使异常发生在截止序号之后——只检查最终余额会放过
1686	//     中间越界的存档；
1687	//   - 曾涉及该账单的收款在被更正移出该月后，仍保留零金额撤销事件。
1688	//
1689	// 只读：不修改库、不占用序号、不新增记录。
1690	func billLedger(s *state, b *bill) ([]ledgerEvent, error) {
1691		ops, err := postbillOps(s, b.CustomerID)
1692		if err != nil {
1693			return nil, err
1694		}
1695		ledgers, err := verifyPostbillLedgers(ops, []*bill{b})
1696		if err != nil {
1697			return nil, err
1698		}
1699		return ledgers[b.Month], nil
1700	}
1701	
1702	func cmdBillLedger(dir, customerID, month, cutoffText string, hasCutoff bool) error {
1703		if !validMonth(month) {
1704			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
1705		}
1706		s, err := loadStore(dir)
1707		if err != nil {
1708			return err
1709		}
1710		cust, ok := s.Customers[customerID]
1711		if !ok {
1712			return fmt.Errorf("客户标识 %q 不存在", customerID)
1713		}
1714		b, ok := s.Bills[billKey(customerID, month)]
1715		if !ok {
1716			return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算）", customerID, month)
1717		}
1718	
1719		// 截止序号使用调整/收款/更正/退款及其撤销共用的已保存全局序号：省略表示最新，
1720		// 0 只返回初始余额，截止包含该序号；因其他客户或月份操作造成的序号
1721		// 空档合法。负数、非整数或超过存档全局序号上限一律拒绝。
1722		cutoff := s.NextSeq
1723		cutoffDesc := "省略，按最新"
1724		if hasCutoff {
1725			v, perr := strconv.ParseInt(strings.TrimSpace(cutoffText), 10, 64)
1726			if perr != nil {
1727				return fmt.Errorf("截止操作序号 %q 不是非负整数: %w", cutoffText, perr)
1728			}
1729			if v < 0 {
1730				return fmt.Errorf("截止操作序号不能为负数，收到 %d", v)
1731			}
1732			if v > s.NextSeq {
1733				return fmt.Errorf("截止操作序号 %d 超过存档全局序号上限 %d", v, s.NextSeq)
1734			}
1735			cutoff = v
1736			cutoffDesc = "指定"
1737		}
1738	
1739		// 先核验目标账单的完整流水：任何异常（即使发生在截止序号之后）都
1740		// 拒绝，不输出部分正常的报告。
1741		events, err := billLedger(s, b)
1742		if err != nil {
1743			return err
1744		}
1745		printBillLedger(b, cust, s.NextSeq, cutoff, cutoffDesc, events)
1746		return nil
1747	}
1748	
1749	func printBillLedger(b *bill, cust *customer, nextSeq, cutoff int64, cutoffDesc string, events []ledgerEvent) {
1750		fmt.Fprintf(stdout, "账单标识：%s\n", b.ID)
1751		fmt.Fprintf(stdout, "客户：%s（%s）\n", cust.ID, cust.Name)
1752		fmt.Fprintf(stdout, "月份：%s（UTC 自然月，左闭右开）\n", b.Month)
1753		fmt.Fprintf(stdout, "原总金额：%d 分（%s）\n", b.TotalFee, moneyFen(b.TotalFee))
1754		fmt.Fprintf(stdout, "存档全局序号上限：%d\n", nextSeq)
1755		fmt.Fprintf(stdout, "截止操作序号：%d（%s）\n", cutoff, cutoffDesc)
1756		fmt.Fprintf(stdout, "初始余额：应付 %d 分（%s），实收 0 分（%s），未收余额 %d 分（%s）\n",
1757			b.TotalFee, moneyFen(b.TotalFee), moneyFen(0), b.TotalFee, moneyFen(b.TotalFee))
1758	
1759		// 截止包含该序号；截止之后的事件（含撤销）既不出现也不影响历史余额。
1760		payable, received := b.TotalFee, int64(0)
1761		var shown []ledgerEvent
1762		for _, ev := range events {
1763			if ev.seq > cutoff {
1764				continue
1765			}
1766			shown = append(shown, ev)
1767			payable, received = ev.afterPayable, ev.afterReceived
1768		}
1769		if len(shown) == 0 {
1770			fmt.Fprintln(stdout, "流水：无（截止序号以内该账单无账后事件）")
1771		} else {
1772			fmt.Fprintln(stdout, "流水（按操作序号升序）：")
1773			for i, ev := range shown {
1774				fmt.Fprintf(stdout, "  %d. %s\n", i+1, formatLedgerEvent(ev))
1775			}
1776		}
1777		fmt.Fprintf(stdout, "截止时余额：应付 %d 分（%s），实收 %d 分（%s），未收余额 %d 分（%s）\n",
1778			payable, moneyFen(payable), received, moneyFen(received), payable-received, moneyFen(payable-received))
1779	}
1780	
1781	// formatLedgerEvent 渲染一条流水事件：序号、类型、原记录标识、金额影响、
1782	// 原因或备注、撤销关联，以及事件后的应付、实收、未收余额；收款类事件同时
1783	// 说明汇款总额与本账单分配。
1784	func formatLedgerEvent(ev ledgerEvent) string {
1785		after := fmt.Sprintf("事后：应付 %d 分，实收 %d 分，未收余额 %d 分",
1786			ev.afterPayable, ev.afterReceived, ev.afterPayable-ev.afterReceived)
1787		switch ev.kind {
1788		case "调整":
1789			return fmt.Sprintf("序号 %d 调整 %s：应付 %+d 分（%s，%s），原因：%s → %s",
1790				ev.seq, ev.refID, ev.deltaPayable, moneyFen(ev.deltaPayable), adjustKind(ev.deltaPayable), ev.note, after)
1791		case "撤销调整":
1792			return fmt.Sprintf("序号 %d 撤销调整 %s：应付 %+d 分（%s，关联序号 %d 的调整 %s），原因：%s → %s",
1793				ev.seq, ev.refID, ev.deltaPayable, moneyFen(ev.deltaPayable), ev.linkSeq, ev.refID, ev.note, after)
1794		case "收款":
1795			return fmt.Sprintf("序号 %d 收款 %s：实收 %+d 分（%s，汇款总额 %d 分，本账单分配 %d 分），备注：%s → %s",
1796				ev.seq, ev.refID, ev.deltaReceived, moneyFen(ev.deltaReceived), ev.payTotal, ev.payAlloc, ev.note, after)
1797		case "更正":
1798			return fmt.Sprintf("序号 %d 更正 %s：实收 %+d 分（%s，关联收款 %s，本账单分配 %d 分 → %d 分），原因：%s → %s",
1799				ev.seq, ev.refID, ev.deltaReceived, moneyFen(ev.deltaReceived), ev.payID, ev.beforeAlloc, ev.afterAlloc, ev.note, after)
1800		case "退款":
1801			return fmt.Sprintf("序号 %d 退款 %s：实收 %+d 分（%s，关联收款 %s，本账单退款 %d 分），原因：%s → %s",
1802				ev.seq, ev.refID, ev.deltaReceived, moneyFen(ev.deltaReceived), ev.payID, ev.payAlloc, ev.note, after)
1803		default: // 撤销收款
1804			return fmt.Sprintf("序号 %d 撤销收款 %s：实收 %+d 分（%s，关联序号 %d 的收款 %s，汇款总额 %d 分，取消本账单分配 %d 分），原因：%s → %s",
1805				ev.seq, ev.refID, ev.deltaReceived, moneyFen(ev.deltaReceived), ev.linkSeq, ev.refID, ev.payTotal, ev.payAlloc, ev.note, after)
1806		}
1807	}
1808

