		"序号 3 撤销收款 r1：实收 -500 分",
		"取消本账单分配 500 分",
		"截止时余额：应付 500 分（5.00 元），实收 0 分（0.00 元），未收余额 500 分（5.00 元）",
	} {
		if !strings.Contains(sep, want) {
			t.Fatalf("9 月流水缺少 %q:\n%s", want, sep)
