		t.Fatal(cut)
	}
	// 最新与 bill show 一致。
	shown := h.mustRun("bill", "show", "c1", "2026-09")
	if !strings.Contains(shown, "实收：0 分") || !strings.Contains(shown, "未收余额：500 分") {
		t.Fatal(shown)
	}
}

