// paymentHistoryEvents 把收款登记、分配更正、归属转出/转入、撤销与退款展开
// 为按操作序号排序的可读历史条目；month 为当前展示账单所在月份（账单客户
// 固定）。只有收款在当时归属本账单客户期间发生的事件才展示：归属转出后本
// 账单不再有该收款的后续事件，转入客户在转入序号之前也不补登收款事件；
// 归属转出在原客户账单保留转出条目，归属转入在新客户账单列转入条目。
func paymentHistoryEvents(s *state, pays []*payment, month string) []string {
	type event struct {
		seq  int64
		text string
	}
	var events []event
	for _, p := range pays {
		timeline, err := buildPaymentTimeline(s, p)
		if err != nil {
			continue
		}
		for _, ev := range timeline {
			switch ev.kind {
			case ptPayment:
				alloc := allocAmountFor(ev.after, month)
				events = append(events, event{ev.seq, fmt.Sprintf("收款 %s：总额 %d 分（%s），本账单分配 %d 分（%s），备注：%s，当前状态：%s（客户 %s）",
					p.ID, p.Total, moneyFen(p.Total), alloc, moneyFen(alloc), p.Note, paymentStatus(p), ev.owner)})
			case ptCorrection:
				after := allocAmountFor(ev.after, month)
				running := allocAmountFor(ev.before, month)
				if running == 0 && after == 0 {
					continue
				}
				events = append(events, event{ev.seq, fmt.Sprintf("更正 %s：原因：%s（关联收款 %s，本账单分配 %d 分 → %d 分）",
					ev.id, ev.note, p.ID, running, after)})
			case ptTransfer:
				// 归属转出只在转出客户账单展示；归属转入只在目标客户账单展示。
				if ev.owner == bCustomerOf(pays) {
					out := allocAmountFor(ev.before, month)
					if out > 0 {
						events = append(events, event{ev.seq, fmt.Sprintf("归属转出 %s：原因：%s（关联收款 %s，总额 %d 分，本账单转出 %d 分至客户 %s）",
							ev.id, ev.note, p.ID, p.Total, out, ev.to)})
					}
				}
				if ev.to == bCustomerOf(pays) {
					in := allocAmountFor(ev.after, month)
					if in > 0 {
						events = append(events, event{ev.seq, fmt.Sprintf("归属转入 %s：原因：%s（关联收款 %s，自客户 %s 转入，总额 %d 分，本账单转入 %d 分）",
							ev.id, ev.note, p.ID, ev.owner, p.Total, in)})
					}
				}
			case ptRefund:
				amt := allocAmountFor(ev.allocs, month)
				if amt <= 0 {
					continue
				}
				events = append(events, event{ev.seq, fmt.Sprintf("退款 %s：原因：%s（关联收款 %s，本账单退款 %d 分（%s））",
					ev.id, ev.note, p.ID, amt, moneyFen(amt))})
			case ptRevoke:
				// 撤销只作用于撤销时的当前归属客户；该客户曾涉及本账单时
				// 展示被取消的最新分配（转出后旧客户此处为 0）。
				running := allocAmountFor(ev.before, month)
				events = append(events, event{ev.seq, fmt.Sprintf("撤销收款 %s：原因：%s（关联收款 %s，总额 %d 分，本账单分配 %d 分）",
					p.ID, ev.note, p.ID, p.Total, running)})
			}
		}
	}
	sort.Slice(events, func(i, j int) bool { return events[i].seq < events[j].seq })
	out := make([]string, len(events))
	for i, ev := range events {
		out[i] = ev.text
	}
	return out
}

// bCustomerOf 从 paymentsEverFor 的结果中反推出账单客户：该列表中的收款
// 可能已转出，但调用方展示的账单客户固定。为避免传参侵入，由调用处直接
// 传入客户标识（见 paymentHistoryEventsFor）。
func bCustomerOf(_ []*payment) string { return "" }

// paymentHistoryEventsFor 是带账单客户标识的历史条目构建入口。
func paymentHistoryEventsFor(s *state, customerID string, pays []*payment, month string) []string {
	var out []string
	for _, line := range paymentHistoryEventsRaw(s, customerID, pays, month) {
		out = append(out, line.text)
	}
	return out
}

type paymentHistoryLine struct {
	seq  int64
	text string
}

func paymentHistoryEventsRaw(s *state, customerID string, pays []*payment, month string) []paymentHistoryLine {
	var events []paymentHistoryLine
	for _, p := range pays {
		timeline, err := buildPaymentTimeline(s, p)
		if err != nil {
			continue
		}
		for _, ev := range timeline {
			switch ev.kind {
			case ptPayment:
				if ev.owner != customerID {
					continue
				}
				alloc := allocAmountFor(ev.after, month)
				events = append(events, paymentHistoryLine{ev.seq, fmt.Sprintf("收款 %s：总额 %d 分（%s），本账单分配 %d 分（%s），备注：%s，当前状态：%s（客户 %s）",
					p.ID, p.Total, moneyFen(p.Total), alloc, moneyFen(alloc), p.Note, paymentStatus(p), ev.owner)})
			case ptCorrection:
				if ev.owner != customerID {
					continue
				}
				b4, af := allocAmountFor(ev.before, month), allocAmountFor(ev.after, month)
				if b4 == 0 && af == 0 {
					continue
				}
				events = append(events, paymentHistoryLine{ev.seq, fmt.Sprintf("更正 %s：原因：%s（关联收款 %s，本账单分配 %d 分 → %d 分）",
					ev.id, ev.note, p.ID, b4, af)})
			case ptTransfer:
				if ev.owner == customerID {
					outAmt := allocAmountFor(ev.before, month)
					if outAmt > 0 {
						events = append(events, paymentHistoryLine{ev.seq, fmt.Sprintf("归属转出 %s：原因：%s（关联收款 %s，总额 %d 分，本账单转出 %d 分至客户 %s）",
							ev.id, ev.note, p.ID, p.Total, outAmt, ev.to)})
					}
				}
				if ev.to == customerID {
					inAmt := allocAmountFor(ev.after, month)
					if inAmt > 0 {
						events = append(events, paymentHistoryLine{ev.seq, fmt.Sprintf("归属转入 %s：原因：%s（关联收款 %s，自客户 %s 转入，总额 %d 分，本账单转入 %d 分）",
							ev.id, ev.note, p.ID, ev.owner, p.Total, inAmt)})
					}
				}
			case ptRefund:
				if ev.owner != customerID {
					continue
				}
				amt := allocAmountFor(ev.allocs, month)
				if amt <= 0 {
					continue
				}
				events = append(events, paymentHistoryLine{ev.seq, fmt.Sprintf("退款 %s：原因：%s（关联收款 %s，本账单退款 %d 分（%s））",
					ev.id, ev.note, p.ID, amt, moneyFen(amt))})
			case ptRevoke:
				if ev.owner != customerID {
					continue
				}
				running := allocAmountFor(ev.before, month)
				events = append(events, paymentHistoryLine{ev.seq, fmt.Sprintf("撤销收款 %s：原因：%s（关联收款 %s，总额 %d 分，本账单分配 %d 分）",
					p.ID, ev.note, p.ID, p.Total, running)})
			}
		}
	}
	sort.Slice(events, func(i, j int) bool { return events[i].seq < events[j].seq })
	return events
}

