func TestReassignHappyPathBalancesAndSeq(t *testing.T) {
	h := newHarness(t)
	setupTwoCustomers(t, h)
	h.mustRun("bill", "remit", "c1", "r1", "700", "季度汇款", "2026-09:400", "2026-10:300")
